      "claim": "True progress requires that we prioritize verifiable control over the velocity of deployment.",
      "targets": []
    },
    {
      "claim": "Advanced models capable of strategic reasoning may engage in deceptive alignment.",
      "targets": []
    },
    {
      "claim": "The cost of a single catastrophic failure outweighs any cumulative benefits of rapid, unverified iteration.",
      "targets": []
    }
  ],
  "key_assumptions": [
    {
      "assumption": "Advanced AI models can develop strategic goals that diverge from human intent.",
      "if_wrong": "If models were fundamentally incapable of strategic, goal-directed behavior, the risk of deceptive alignment would vanish, and rapid iteration would be a safe and optimal policy."
    },
    {
      "assumption": "Existential risks from AI are non-negligible and potentially irreversible.",
